import sys
from math import gcd

sys.setrecursionlimit(200000)

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    n = int(next(iterator))

    x = [0] * (n + 1)
    for i in range(1, n + 1):
        x[i] = int(next(iterator))

    adj = [[] for _ in range(n + 1)]
    for _ in range(n - 1):
        u = int(next(iterator))
        v = int(next(iterator))
        adj[u].append(v)
        adj[v].append(u)

    MOD = 10**9 + 7

    parent = [0] * (n + 1)
    order = []
    stack = [1]
    visited = [False] * (n + 1)
    visited[1] = True

    while stack:
        u = stack.pop()
        order.append(u)
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                parent[v] = u
                stack.append(v)

    dp = [{} for _ in range(n + 1)]
    total_sum = 0

    for u in reversed(order):
        current_gcds = {}
        val = x[u]

        if val == 0:
            current_gcds[0] = 1
        else:
            current_gcds[val] = 1

        if parent[u] != 0:
            p = parent[u]
            for g, count in dp[p].items():
                new_g = gcd(g, val)
                if new_g in current_gcds:
                    current_gcds[new_g] += count
                else:
                    current_gcds[new_g] = count

        dp[u] = current_gcds

        for g, count in current_gcds.items():
            term = (g % MOD) * (count % MOD)
            total_sum = (total_sum + term) % MOD

    print(total_sum)

if __name__ == "__main__":
    main()
